#!/bin/sh
# Prints Lock_File entries (deps/lock.toml) for the solvers and for why3find
# on the platform it runs on, from the Nix builds of this flake (R7.7).
#
#   deps/gen-lock.sh > deps/lock.toml      (from the repository root)
#
# Still missing (tools/lock-check lists what is pending and why):
# the other platforms, the OCaml toolchain and libraries, and the evidence
# of R7.7 criterion 9 for each Unpatched_Solver entry, which is why
# `rebuild_hashes` is empty.
#
# Finding (2026-11-17, aarch64-darwin): `nix build --rebuild` reports that the
# builds of alt-ergo, z3, cvc5 and ethos are not bit-for-bit reproducible on
# macOS, so two rebuilds do not give equal hashes there. On this platform the
# evidence has to be an upstream-published checksum, or the check has to run
# on Linux.
set -eu

platform=$(nix eval --raw --impure --expr builtins.currentSystem)
sha() {
  if command -v sha256sum > /dev/null; then sha256sum "$1"; else shasum -a 256 "$1"; fi | cut -d' ' -f1
}
# Creusot's wrapper is what puts the solvers on PATH; hash the files it links to.
wrapper=$(nix build .#creusot --no-link --print-out-paths)
real() { python3 -c 'import os,sys; print(os.path.realpath(sys.argv[1]))' "$1"; }

cat <<HEADER
# Lock_File (R7.7). Generated by deps/gen-lock.sh; do not edit.
# Partial: solvers and why3find on the platforms listed, no rebuild hashes yet.
HEADER

solver() { # name prover version tag
  file=$(real "$wrapper/bin/$1")
  cat <<ENTRY

[[tool]]
name = "$1"
version = "$3"
kind = "unpatched-solver"
prover = "$2"

[[tool.platform]]
platform = "$platform"
hash = "sha256:$(sha "$file")"
upstream = { tag = "$4", rebuild_hashes = [] }
ENTRY
}

solver alt-ergo alt-ergo 2.6.4 v2.6.4
solver z3 z3 5.3.2 z3-5.3.2
solver cvc5 cvc5 1.4.1 cvc5-1.4.1
solver cvc4 cvc4 1.8 cvc4-1.8

# The checker of certificates and its signature files (R5.3, TB-11). The
# hash of the signature is the hash of the listing of its files:
# `<sha256>  ./<path>` per file, in the order of the paths, as dp-cert
# computes it.
ethos=$(nix build .#ethos --no-link --print-out-paths)
signature=$(nix build .#cpc-signature --no-link --print-out-paths)
tree() {
  (cd "$1" && find . -type f | LC_ALL=C sort | while read -r f; do printf '%s  %s\n' "$(sha "$f")" "$f"; done) > "${TMPDIR:-/tmp}/dp-tree.$$"
  sha "${TMPDIR:-/tmp}/dp-tree.$$"
  rm -f "${TMPDIR:-/tmp}/dp-tree.$$"
}
cat <<ENTRY

[[tool]]
name = "ethos"
version = "c7d3db90"
kind = "checker"

[[tool.platform]]
platform = "$platform"
hash = "sha256:$(sha "$(real "$ethos/bin/ethos")")"

[[tool]]
name = "cpc-signature"
version = "cvc5-1.4.1"
kind = "checker-signature"

[[tool.platform]]
platform = "$platform"
hash = "sha256:$(tree "$signature")"
ENTRY

why3find=$(nix build .#why3find-dispatch --no-link --print-out-paths)
cat <<ENTRY

[[tool]]
name = "why3find-dispatch"
version = "89dd8721fb9de7fea5d00e58ebdabdc75a8235b8"
kind = "why3find"
patches = ["patches/why3find/0001-dispatch-mode.patch"]

[[tool.platform]]
platform = "$platform"
hash = "sha256:$(sha "$(real "$why3find/bin/why3find")")"
ENTRY

# Creusot_CLI with the backend option (R7.9). Never an Unpatched_Solver kind.
cat <<ENTRY

[[tool]]
name = "creusot"
version = "fd4d85b2c237ef93147e99f6a0c04acfc89a6a17"
kind = "creusot"
patches = ["patches/creusot/0001-prove-backend-option.patch"]

[[tool.platform]]
platform = "$platform"
hash = "sha256:$(sha "$(real "$wrapper/bin/cargo-creusot")")"
ENTRY

# The other tools of R7.7 criterion 1. The hash is that of the tool's
# entry point in its Nix build: the file that is run.
other() { # package binary name kind [version]
  out=$(nix build ".#$1" --no-link --print-out-paths | head -1)
  # The version is the end of the store path's name, after the package name.
  version=${5:-$(basename "$out" | sed -E 's/^[a-z0-9]{32}-//; s/^[a-zA-Z0-9]*(-[a-zA-Z][a-zA-Z0-9]*)*-//')}
  cat <<ENTRY

[[tool]]
name = "$3"
version = "$version"
kind = "$4"

[[tool.platform]]
platform = "$platform"
hash = "sha256:$(sha "$(real "$out/bin/$2")")"
ENTRY
}

other why3 why3 why3 why3 05bf4ddf55cb3042f34c3bc0ed3aff56a226978a
other carcara carcara carcara checker 394edbb15ba95c47893f1d821fddde7e016af178
other lean lean lean lean
other tlc tlc tlc tla
other apalache apalache-mc apalache tla
other kani kani kani kani
other cargo-mutants cargo-mutants cargo-mutants cargo-mutants
other rust-toolchain cargo rust-toolchain toolchain

# The Rust libraries of the System: the lock file of the workspace, without
# the `source` and `checksum` lines of the packages that Creusot's shell
# provides from its own build (inside the shell cargo writes their entries
# without them). tools/lock-check computes the same text.
normalized=${TMPDIR:-/tmp}/dp-cargo-lock.$$
awk '
  $0 == "[[package]]" { provided = 0 }
  /^name = "/ { provided = ($0 == "name = \"creusot-std\"" || $0 == "name = \"creusot-std-proc\"" || $0 == "name = \"pearlite-syn\"") }
  provided && (/^source = / || /^checksum = /) { next }
  { print }
' Cargo.lock > "$normalized"
cat <<ENTRY

[[tool]]
name = "rust-libraries"
version = "Cargo.lock"
kind = "library"

[[tool.platform]]
platform = "$platform"
hash = "sha256:$(sha "$normalized")"
ENTRY
rm -f "$normalized"
